INSERT INTO price_sample_review(sample_id,revision,status,part_id,model_id,amount,unit,price_nature,reason,created_by)
 SELECT x.id,1,'CONFIRMED',x.part,x.model,x.amount,x.unit,x.nature,x.reason,#{actor}
 FROM jsonb_to_recordset(CAST(#{rows} AS jsonb)) AS x(id uuid,part bigint,model bigint,amount numeric,unit text,nature text,reason text)
